from ortools.linear_solver import pywraplp
import json

def main():
    workflows = ['Alpha', 'Beta', 'Gamma', 'Delta', 'Epsilon']
    stations = [1, 2, 3, 4, 5]

    sequence = {
        'Alpha': [1, 3, 2, 5, 4],
        'Beta': [2, 1, 4, 3, 5],
        'Gamma': [3, 5, 1, 2, 4],
        'Delta': [4, 2, 5, 1, 3],
        'Epsilon': [5, 4, 3, 2, 1]
    }

    duration = {
        'Alpha': {1: 12, 3: 8, 2: 15, 5: 20, 4: 10},
        'Beta': {2: 25, 1: 12, 4: 18, 3: 14, 5: 22},
        'Gamma': {3: 16, 5: 30, 1: 9, 2: 12, 4: 25},
        'Delta': {4: 18, 2: 15, 5: 12, 1: 28, 3: 16},
        'Epsilon': {5: 20, 4: 14, 3: 25, 2: 16, 1: 18}
    }

    solver = pywraplp.Solver.CreateSolver('SCIP')
    INF = solver.infinity()

    start_time = {}
    for w in workflows:
        for k in range(1, 6):
            start_time[(w, k)] = solver.NumVar(0, INF, f'start_{w}_{k}')

    makespan = solver.NumVar(0, INF, 'makespan')

    for w in workflows:
        for k in range(1, 5):
            current_station = sequence[w][k-1]
            next_station = sequence[w][k]
            solver.Add(
                start_time[(w, k+1)] >= 
                start_time[(w, k)] + duration[w][current_station]
            )

    for s in stations:
        operations = []
        for w in workflows:
            for k in range(1, 6):
                if sequence[w][k-1] == s:
                    operations.append((w, k))

        for i in range(len(operations)):
            for j in range(i+1, len(operations)):
                w1, k1 = operations[i]
                w2, k2 = operations[j]

                b = solver.BoolVar(f'b_{w1}_{k1}_{w2}_{k2}')

                M = 10000

                solver.Add(
                    start_time[(w1, k1)] + duration[w1][s] <= 
                    start_time[(w2, k2)] + M * (1 - b)
                )

                solver.Add(
                    start_time[(w2, k2)] + duration[w2][s] <= 
                    start_time[(w1, k1)] + M * b
                )

    for w in workflows:
        last_station = sequence[w][4]
        solver.Add(
            start_time[(w, 5)] + duration[w][last_station] <= makespan
        )

    solver.Minimize(makespan)

    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        initiation_times = []
        for w in workflows:
            times = []
            for k in range(1, 6):
                times.append(round(start_time[(w, k)].solution_value()))
            initiation_times.append(times)
        production_completion_duration = round(makespan.solution_value())
    else:
        initiation_times = []
        production_completion_duration = 0

    print(json.dumps({
        "initiation_times": initiation_times,
        "production_completion_duration": production_completion_duration
    }))

if __name__ == '__main__':
    main()
